// Decides which sitemap files to read.
// - Sitemap index (WordPress, Shopify, Wix…) → read the useful child sitemaps
// - Normal sitemap → read it
// - Always: the homepage, so its links find pages the sitemap forgot
const cfg = $('Config').first().json;
const site = String(cfg.website_url || '').trim().replace(/\/+$/, '');
if (!/^https?:\/\//i.test(site)) {
  throw new Error('Set website_url in the Config node (it must start with https://)');
}
const sitemapUrl = String(cfg.sitemap_url || '').trim() || `${site}/sitemap.xml`;
const xml = typeof $input.first().json.data === 'string' ? $input.first().json.data : '';
const decode = (s) => s.replace(/&amp;/g, '&').trim();
const locs = [...xml.matchAll(/<loc>\s*(?:<!\[CDATA\[)?\s*([^<\s\]]+)\s*(?:\]\]>)?\s*<\/loc>/gi)].map((m) => decode(m[1]));

let urls;
if (/<sitemapindex[\s>]/i.test(xml)) {
  const skip = /(image|video|author|tag|attachment|media|news)[-_]?sitemap|sitemap[-_](image|video|author|tag)/i;
  const prefer = /(page|post|product|service|blog|article|collection|location|faq|category)/i;
  urls = locs
    .filter((u) => !skip.test(u))
    .sort((a, b) => Number(prefer.test(b)) - Number(prefer.test(a)))
    .slice(0, 10);
  if (!urls.length) urls = locs.slice(0, 5);
} else if (/<urlset[\s>]/i.test(xml)) {
  urls = [sitemapUrl];
} else {
  urls = [];
}
// Always read the homepage too: its menu links find pages missing from the sitemap
urls.unshift(site);
return urls.map((url) => ({ json: { url } }));

// Collects the pages to learn from: sitemap entries + links found on the
// homepage + any extra URLs from Config. Keeps only pages on your domain and
// puts the most useful ones (pricing, FAQ, contact…) first.
// --- Tiny URL helper (n8n's Code node sandbox has no URL class) -------------
function resolveUrl(href, base) {
  href = String(href || '').trim().replace(/&amp;/g, '&');
  if (!href || /^(mailto:|tel:|javascript:|data:|sms:|whatsapp:|#)/i.test(href)) return null;
  const b = String(base || '').match(/^(https?:)\/\/([^\/?#]+)([^?#]*)/i);
  let proto, host, path, query = '';
  let m;
  if ((m = href.match(/^(https?:)\/\/([^\/?#]+)([^?#]*)(\?[^#]*)?/i))) {
    [, proto, host, path, query = ''] = m;
  } else if (href.startsWith('//') && b) {
    m = href.match(/^\/\/([^\/?#]+)([^?#]*)(\?[^#]*)?/);
    if (!m) return null;
    proto = b[1];
    [, host, path, query = ''] = m;
  } else if (/^[a-z][a-z0-9+.-]*:/i.test(href) || !b) {
    return null;
  } else {
    proto = b[1];
    host = b[2];
    const rel = href.match(/^([^?#]*)(\?[^#]*)?/);
    query = rel[2] || '';
    if (rel[1].startsWith('/')) path = rel[1];
    else if (rel[1] === '') path = b[3] || '/';
    else path = (b[3] || '/').replace(/[^\/]*$/, '') + rel[1];
  }
  const segments = [];
  for (const s of (path || '/').split('/')) {
    if (s === '..') segments.pop();
    else if (s !== '.') segments.push(s);
  }
  path = segments.join('/');
  if (!path.startsWith('/')) path = '/' + path;
  proto = proto.toLowerCase();
  host = host.toLowerCase();
  return {
    protocol: proto,
    host,
    hostname: host.replace(/:\d+$/, ''),
    domain: host.replace(/:\d+$/, '').replace(/^www\./, ''),
    pathname: path,
    search: query,
    origin: `${proto}//${host}`,
    href: `${proto}//${host}${path}${query}`,
  };
}
// ---------------------------------------------------------------------------

const cfg = $('Config').first().json;
const site = String(cfg.website_url || '').trim().replace(/\/+$/, '');
const siteUrl = resolveUrl(site);
if (!siteUrl) throw new Error('website_url in the Config node must start with https://');
const maxPages = Math.max(1, Math.min(Number(cfg.max_pages) || 40, 300));
const TRACKING = /^(utm_[a-z]+|fbclid|gclid|ref|mc_cid|mc_eid)$/i;

const pages = new Map(); // url -> priority bonus
function add(raw, bonus = 0) {
  const url = resolveUrl(raw, site + '/');
  if (!url || url.domain !== siteUrl.domain) return;
  if (/\.(jpe?g|png|gif|webp|svg|ico|pdf|zip|rar|mp4|mp3|wav|css|js|json|xml|txt|woff2?|ttf|eot)$/i.test(url.pathname)) return;
  if (/(\/wp-admin|\/wp-json|\/wp-login|\/cart|\/checkout|\/my-account|\/account|\/login|\/signin|\/register|\/feed\/?$|\/tag\/|\/author\/|\/cdn-cgi\/|\/search)/i.test(url.pathname)) return;
  const params = url.search.replace(/^\?/, '').split('&').filter(Boolean).filter((p) => !TRACKING.test(p.split('=')[0]));
  if (params.length) return; // skip filtered / paginated variants
  const clean = (url.origin + url.pathname).replace(/\/$/, '');
  pages.set(clean, Math.max(pages.get(clean) || 0, bonus));
}

add(site, 1000);
for (const extra of String(cfg.extra_page_urls || '').split(/[\s,]+/)) if (extra) add(extra, 500);

for (const item of $input.all()) {
  const body = typeof item.json.data === 'string' ? item.json.data : '';
  for (const m of body.matchAll(/<loc>\s*(?:<!\[CDATA\[)?\s*([^<\s\]]+)/gi)) add(m[1]);
  for (const m of body.matchAll(/<a\s[^>]*?href\s*=\s*["']([^"'#][^"']*)["']/gi)) add(m[1]);
}

const IMPORTANT = /(about|contact|pricing|price|plans|faq|help|support|service|product|shipping|delivery|return|refund|warranty|policy|terms|book|appointment|location|hours|team|menu|course)/i;
function score(url) {
  const path = (resolveUrl(url) || { pathname: '/' }).pathname.toLowerCase();
  let s = pages.get(url) || 0;
  if (path === '/' || path === '') s += 100;
  if (IMPORTANT.test(path)) s += 50;
  s -= path.split('/').filter(Boolean).length * 5;
  return s;
}

const selected = [...pages.keys()].sort((a, b) => score(b) - score(a)).slice(0, maxPages);
return selected.map((url, index) => ({ json: { url, isHomepage: index === 0 } }));

// Turns every downloaded page into clean, readable text for the knowledge base.
const cfg = $('Config').first().json;
const pages = $('Collect Page URLs').all();

const NAMED = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', ndash: '–', mdash: '—', hellip: '…', rsquo: '’', lsquo: '‘', rdquo: '”', ldquo: '“', copy: '©', reg: '®', trade: '™', euro: '€', pound: '£', yen: '¥', cent: '¢', deg: '°', times: '×', middot: '·', bull: '•' };
function decodeEntities(s) {
  return s.replace(/&(#x?[0-9a-f]+|[a-z]+);/gi, (match, entity) => {
    if (entity[0] === '#') {
      const code = entity[1].toLowerCase() === 'x' ? parseInt(entity.slice(2), 16) : parseInt(entity.slice(1), 10);
      return Number.isFinite(code) && code > 0 && code < 0x110000 ? String.fromCodePoint(code) : match;
    }
    return NAMED[entity.toLowerCase()] ?? match;
  });
}

function htmlToText(html, keepLayout) {
  let h = String(html).slice(0, 2000000);
  const title = decodeEntities(((h.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || '').replace(/\s+/g, ' ').trim());
  const description = decodeEntities(((h.match(/<meta[^>]+name=["']description["'][^>]*content=["']([^"']*)["']/i) || h.match(/<meta[^>]+content=["']([^"']*)["'][^>]*name=["']description["']/i) || [])[1] || '').trim());
  h = h.replace(/<head[\s\S]*?<\/head>/i, ' ');
  h = h.replace(/<!--[\s\S]*?-->/g, ' ');
  h = h.replace(/<(script|style|noscript|svg|iframe|template|canvas|select)[\s\S]*?<\/\1>/gi, ' ');
  // Menus repeat on every page – keep header/footer only for the homepage (contact details live there)
  h = h.replace(/<nav[\s\S]*?<\/nav>/gi, ' ');
  if (!keepLayout) h = h.replace(/<(header|footer)[\s\S]*?<\/\1>/gi, ' ');
  h = h.replace(/<(h[1-6])[^>]*>([\s\S]*?)<\/\1>/gi, (m, tag, inner) => `\n\n${'#'.repeat(Number(tag[1]))} ${inner.replace(/<[^>]+>/g, ' ')}\n`);
  h = h.replace(/<li[^>]*>/gi, '\n- ');
  h = h.replace(/<(br|hr)\s*\/?>/gi, '\n');
  h = h.replace(/<\/(p|div|section|article|li|tr|table|ul|ol|blockquote|dd|dt|figure|address)>/gi, '\n');
  h = h.replace(/<(td|th)[^>]*>/gi, ' | ');
  h = h.replace(/<[^>]+>/g, ' ');
  const text = decodeEntities(h)
    .replace(/[ \t\f\v ]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  return { title, description, text };
}

const out = [];
$input.all().forEach((item, i) => {
  const page = pages[i] && pages[i].json;
  const html = typeof item.json.data === 'string' ? item.json.data : '';
  if (!page || !html || item.json.error) return;
  const { title, description, text } = htmlToText(html, page.isHomepage);
  if (text.length < 150) return;
  out.push({
    json: {
      url: page.url,
      title: title || page.url,
      content: `# ${title || page.url}\nSource: ${page.url}\n${description ? `Summary: ${description}\n` : ''}\n${text.slice(0, 25000)}`,
    },
  });
});

const extra = String(cfg.extra_knowledge || '').trim();
if (extra.length > 10) {
  out.push({ json: { url: cfg.website_url, title: 'Extra business information', content: `# Extra business information\nSource: provided by the business\n\n${extra}` } });
}

if (!out.length) {
  throw new Error('No readable pages found. Check website_url in the Config node, or list important pages in extra_page_urls.');
}
return out;
